CREATE TABLE [dbo].[TBLBLOG] (
    [BLOGID] int IDENTITY(1,1) NOT NULL,
    [BASLIK] nvarchar(150) NULL,
    [RESIM] nvarchar(250) NULL,
    [TARIH] date NULL,
    [OZET] nvarchar(500) NULL,
    [ACIKLAMA] nvarchar(max) NULL,
    [BEGENI] int NULL,
    [KATEGORI] int NULL,
    [YAZAR] nvarchar(150) NULL,
    [GORUNTULENME] int NULL,
    [DURUM] bit NULL,
    [SEHIR] nvarchar(50) NULL,
    CONSTRAINT [PK_TBLBLOG] PRIMARY KEY ([BLOGID])
);
GO

