SET IDENTITY_INSERT [dbo].[TBLBLOG] ON;
INSERT INTO [dbo].[TBLBLOG] ([BLOGID], [BASLIK], [RESIM], [TARIH], [OZET], [ACIKLAMA], [BEGENI], [KATEGORI], [YAZAR], [GORUNTULENME], [DURUM], [SEHIR]) VALUES (1, N'UZUNGÖL TRABZON', N'd639e1f5-6c61-475e-acd5-2f5dc0480285.jpg', '2025-07-01', N'DDDDeniz seviyesinden 1090 m yükseklikte bulunan Uzungöl, Türkiye''nin Trabzon ilinde yer alan Çaykara ilçesine bağlı bir turistik mahalledir. Adını kıyısında bulunduğu Uzungöl’den alır. Heyelan set gölü olan Uzungöl, Yamaçlardan düşen kayaların, Haldizen deresinin önünü kapatmasıyla oluşmuştur. Uzunluğu 1.000 m, genişliği 500 m dir. ', N'SSSSoğanlı ve Kaçkar Sıradağları''nın birleşim yerinde bulunmaktadır. Bu bölge aynı zamanda yerkürenin ılıman bölgede bulunan en yaşlı ormanlarına ev sahipliği yapmaktadır. Bol yağış ve nisbi ılıman iklimi sayesinde yılın her mevsiminde yeşildir. Demirkapı ve Soğanlı dağlarında tespit edilmiş 60''tan fazla endemik bitki türü bulunmaktadır. Yabani hayvan hayatı açısından da zengin bir çevre içerir. Uzungöl Özel Çevre Koruma Bölgesi’nde toplam 59 adet memeli ve 250 adet kuş türü tespit edilmiştir. Burada memeli hayvanlardan, Boz ayı, Karaca, Kurt, Çakal, Tilki, Yaban domuzu, Vaşak, Porsuk, Sansar, Su samuru, Çengel boynuzlu dağ keçisi, Yaban keçisi vb türler bulunmaktadır.', 0, 1, N'Admin2', 45, 1, N'TRABZON');
INSERT INTO [dbo].[TBLBLOG] ([BLOGID], [BASLIK], [RESIM], [TARIH], [OZET], [ACIKLAMA], [BEGENI], [KATEGORI], [YAZAR], [GORUNTULENME], [DURUM], [SEHIR]) VALUES (2, N'KAPADOKYA', N'kapadokyakapak.jpg', '2024-07-10', N'Kapadokya Bölgesi tarih içerisinde çeşitli devlet, toplum ve önemli kişilerin adlarıyla anılan dönemler yaşamıştır. Kapadokya Bölgesi''nin tarihi M.Ö. 3000''1ere Asur ticaret kolonileri ve Hititlere kadar gitmektedir. Kapadokya Bölgesi''ni üç ana dönemde incelemek mümkündür. Birinci dönem paleolitik, neolitik ve antik dönemlerdir. İkinci dönem Roma ve Bizans dönemleri ve son dönem Türk dönemidir.', N'Kapadokya bölgesi, doğa ve tarihin bütünleştiği bir yerdir. Coğrafi olaylar Peribacaları''nı oluştururken, tarihi süreçte, insanlar da bu peribacalarının içlerine evler, kiliseler ve manastırlar oymuş bunları fresklerle süsleyerek binlerce yıllık medeniyetlerin izlerini günümüze taşımıştır. İnsan yerleşimlerinin Paleolitik döneme kadar uzandığı Kapadokya''nın yazılı tarihi Hititlerle başlar. Tarih boyunca ticaret kolonilerini barındıran ve ülkeler arasında ticari ve sosyal bir köprü kuran Kapadokya, İpek Yolu''nun da önemli kavşaklarından biridir.

MÖ 12. yüzyılda Hitit İmparatorluğu''nun çöküşüyle bölgede karanlık bir dönem başlar. Bu dönemde Asur ve Frigya etkileri taşıyan geç Hitit Kralları bölgeye egemen olur. Bu Krallıklar MÖ 6. yüzyıldaki Pers işgaline kadar sürer.

MÖ 332 yılında Büyük İskender Persleri yenilgiye uğratır, ama Kapadokya''da büyük bir dirençle karşılaşır. Bu dönemde Kapadokya Krallığı kurulur. MÖ 3. yüzyıl sonlarına doğru Romalıların gücü bölgede hissedilmeye başlar. MÖ 1. yüzyıl ortalarında Kapadokya Kralları, Romalı generallerin gücüyle atanmakta ve tahttan indirilmektedir. MS 17 yılında son Kapadokya kralı ölünce bölge Roma''nın bir eyaleti olur.', 0, 2, N'Admin', 7, 1, N'NEVŞEHİR');
INSERT INTO [dbo].[TBLBLOG] ([BLOGID], [BASLIK], [RESIM], [TARIH], [OZET], [ACIKLAMA], [BEGENI], [KATEGORI], [YAZAR], [GORUNTULENME], [DURUM], [SEHIR]) VALUES (3, N'TOKYO', N'tokyokapak.jpg', '2025-03-10', N'Şibuya''daki Tokyo Yeni Ulusal Tiyatro, opera, bale, çağdaş dans ve drama dahil olmak üzere sahne sanatlarının ulusal merkezidir. Tokyo ayrıca samimi kulüplerden Nippon Budokan gibi uluslararası ünlü alanlara kadar değişen büyüklükteki mekanlarda modern Japon ve uluslararası pop ve rock müziğine ev sahipliği yapar.', N'Uzak Doğu ve Japon mutfağı denildiğinde ilk akla gelen yemeklerin başında suşi geliyor. Çok sayıda suşi restoranı bulabilirsiniz. Nigiri-zushi denilen pirincin tatlı sirke ile tatlandırılmış versiyonu ise en çok yenilen suşi çeşidi. Baharatlarla lezzeti arttırılmış olan yakitori yani barbekü tavuk da Tokyo’ya gidenlerin tatması gereken yemeklerden birisi.

Yemek için gidilebilecek mekanları üçe ayırabiliriz. İlki Kaiten Zushi adı verilen fiyatları uygun olan suşi sunan restoranları, ikincisi Izakaya isimli yemek ve içecek bulabileceğiniz Japon tarzı tavernalar.  Diğer mekan stili ise menü almayı planlayanlar için bir çorba ve 3 çeşit yemek sunan Kaiseki Ryori tarzı mekanlar.', 0, 3, N'Admin', 8, 1, N'TOKYO');
INSERT INTO [dbo].[TBLBLOG] ([BLOGID], [BASLIK], [RESIM], [TARIH], [OZET], [ACIKLAMA], [BEGENI], [KATEGORI], [YAZAR], [GORUNTULENME], [DURUM], [SEHIR]) VALUES (1002, N'deneme', N'8111a86b-b02c-48ff-90b3-55ef2c3056a3.png', '2025-10-12', N'deneme özet', N'<p>deneme açıklama</p>', 0, 1, N'Admin', 4, 1, N'ASD');
