INSERT INTO [dbo].[TBLHAKKIMDA] ([ID], [ADSOYAD], [ADRES], [TEL], [INSTAGRAM], [FACE], [FOTO], [HAKKIMDA]) VALUES (1, N'Zeynep BAŞAR', N'ZMYO', N'6666666666666666', N'https://www.instagram.com/milliyetcomtr/', N'https://www.facebook.com/milliyet.com.tr/?locale=tr_TR', N'adminfoto.jpg', N'Merhabalar, Biz, Asya ve Umut, tanıştığı andan itibaren birlikte gezen bir çiftiz. Yaklaşık beş yıl önce, iş hayatımıza biraz ara verip yüksek lisans yapmak için Almanya’ya taşındık. Yolumuz kimi zaman komşu Yunanistan’a, kimi zaman Küba’ya düştü. Az gittik uz gittik dere tepe düz gittik derken, yol hikayelerimiz birikti ve bunları bu blog’da paylaşmaya karar verdik.');
GO

