INSERT INTO [dbo].[TBLICERIK] ([ID], [BASLIK], [ICERIK], [TARIH], [DOSYA]) VALUES (6, N'aaaaa', N'<ul class="post-categories" style="box-sizing: border-box; list-style: none; padding: 0px; margin: 0px; display: inline-block;"><li style="box-sizing: inherit; padding: 0px; margin: 0px; display: inline-block;"><a href="https://toguhaber.gop.edu.tr/kategori/kampus" rel="category tag" style="box-sizing: inherit; background-color: transparent; color: rgb(6, 90, 173); text-decoration: none; transition: 0.2s; border-color: rgb(10, 113, 192); text-transform: uppercase; padding: 0px 5px;">KAMPÜS</a></li></ul><p><span class="cat-links" style="box-sizing: inherit; color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);"></span><span style="color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);">&nbsp;</span><span class="posted-on mt-clearfix" itemprop="datePublished" style="box-sizing: inherit; position: relative; margin-left: 64px; color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);"><a href="https://toguhaber.gop.edu.tr/h/12625" rel="bookmark" style="box-sizing: inherit; color: rgb(136, 136, 136); transition: 0.2s; border-color: rgb(10, 113, 192); font-size: 14px;">15 Nisan 2026</a></span><span style="color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);"></span></p><div class="entry-thumbnail single-entry-thumbnail mt-clearfix" style="box-sizing: inherit; margin: 30px 0px; color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);"><figure class="post-thumb cover-image" style="margin: 0px; box-sizing: inherit; line-height: 0; position: relative;"><img width="1600" height="1066" src="https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2.jpeg" class="attachment-full size-full wp-post-image" alt="Üniversitemizden KBRN Farkındalık Eğitimi ve Tatbikatı Gerçekleştirildi" itemprop="image" decoding="async" srcset="https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2.jpeg 1600w, https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2-450x300.jpeg 450w, https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2-901x600.jpeg 901w, https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2-225x150.jpeg 225w, https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2-768x512.jpeg 768w, https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/16-2-1536x1023.jpeg 1536w" sizes="(max-width: 1600px) 100vw, 1600px" style="box-sizing: inherit; height: 559.641px; max-width: 100%; width: 840px; object-fit: cover;"></figure></div><div class="entry-meta single-entry-meta" style="box-sizing: inherit; display: flex; justify-content: space-between; align-items: center; padding-bottom: 25px; border-bottom: 1px solid rgb(204, 204, 204); color: rgb(61, 61, 61); font-family: Muli; text-align: center; background-color: rgb(249, 249, 249);"><div class="entry-meta-posted-by posted-by-wrap" style="box-sizing: inherit; display: flex; align-items: center;"><span class="byline" style="box-sizing: inherit;"><span class="author vcard" style="box-sizing: inherit;"><a class="url fn n" href="https://toguhaber.gop.edu.tr/h/author/kurumsaliletisim" style="box-sizing: inherit; color: rgb(51, 51, 51); transition: 0.2s; border-color: rgb(10, 113, 192); font-weight: 600;">Kurumsal İletişim Koordinatörlüğü</a></span></span></div><div class="entry-meta-comment comment-mark" style="box-sizing: inherit;"></div><div class="post-views content-post post-12625 entry-meta load-static" style="box-sizing: inherit; line-height: 1.3;"><span class="post-views-label" style="box-sizing: inherit; margin-right: 0px !important; padding-right: 5px; cursor: pointer;"><span class="dashicons dashicons-share" title="Paylaş" style="box-sizing: inherit; font-family: dashicons; display: inline-block; line-height: 1; text-decoration: inherit; text-rendering: auto; -webkit-font-smoothing: antialiased; width: 20px; height: 20px; font-size: 20px; vertical-align: top; transition: color 0.1s ease-in;"></span>Paylaş</span>&nbsp;<span class="post-views-count" style="box-sizing: inherit; margin-right: 0px !important; font-weight: bold;"><span class="dashicons dashicons-visibility" style="box-sizing: inherit; font-family: dashicons; display: inline-block; line-height: 1; font-weight: 400; text-decoration: inherit; text-rendering: auto; -webkit-font-smoothing: antialiased; width: 20px; height: 20px; font-size: 20px; vertical-align: top; transition: color 0.1s ease-in;"></span>87</span></div></div><div class="entry-content single-entry-summary mt-clearfix" itemprop="text" style="box-sizing: inherit; counter-reset: footnotes 0; margin: 1.5rem 0px 30px; color: rgb(61, 61, 61); font-family: Muli; background-color: rgb(249, 249, 249);"><p style="box-sizing: inherit; margin: 0px 0px 30px; padding: 0px; line-height: 1.8; line-break: auto; text-align: justify;">Üniversitemiz Eczacılık Fakültesi ile AFAD iş birliğinde düzenlenen “Kimyasal, Biyolojik, Radyoaktif ve Nükleer (KBRN) Farkındalık Eğitimi ve Tatbikatı”, 15 Nisan 2026 Çarşamba günü yoğun katılımla gerçekleştirildi. Eğitime Eczacılık Fakültesi Dekanı Prof. Dr. Bilge Hilal Çadırcı, Erbaa Sağlık Bilimleri Fakültesi Dekanı Prof. Dr. Fatih Polat, akademik ve idari personel ile öğrenciler katıldı.</p><p style="box-sizing: inherit; margin: 0px 0px 30px; padding: 0px; line-height: 1.8; line-break: auto; text-align: justify;">Program kapsamında, AFAD Arama Kurtarma Ekibinden Yunis Utanç ve Sercan Güher tarafından katılımcılara kapsamlı bir eğitim verildi. Eğitimde, ikaz ve alarm işaretlerinin anlamları, sığınakların önemi ve olası KBRN tehditleri karşısında alınması gereken önlemler detaylı şekilde ele alındı.</p><p style="box-sizing: inherit; margin: 0px 0px 30px; padding: 0px; line-height: 1.8; line-break: auto; text-align: justify;">Şehit Ömer Halisdemir Konferans Salonu’nda saat 10.00’da başlayan programda, KBRN tehditlerine karşı hazırlık süreçleri, kriz anında doğru müdahale yöntemleri ve bireysel farkındalığın önemi üzerinde duruldu. Alanında uzman eğitmenler tarafından sunulan içeriklerle katılımcılara hem teorik hem de uygulamaya yönelik önemli bilgiler aktarıldı.</p><p style="box-sizing: inherit; margin: 0px 0px 30px; padding: 0px; line-height: 1.8; line-break: auto; text-align: justify;">Eğitimin ardından gerçekleştirilen tatbikatta ise senaryo gereği oluşturulan olay alanında ekipler, kimyasal ve biyolojik risklere karşı müdahale süreçlerini uygulamalı olarak sergiledi. Koruyucu ekipman kullanımı, olay yeri güvenliğinin sağlanması ve dekontaminasyon aşamaları katılımcılar tarafından ilgiyle takip edildi.&nbsp;&nbsp;</p><figure class="wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex" style="margin: 1em 0px 30px; box-sizing: inherit; gap: 8px; flex-wrap: wrap; align-items: normal; display: flex; --wp--style--unstable-gallery-gap: 0.5em; text-align: center; justify-content: center;"><figure class="wp-block-image size-large" style="margin: 0px; justify-content: center; display: flex; flex-direction: column; flex-grow: 1; max-width: 100%; position: relative; width: calc(33.33% - 5.33336px); align-self: inherit;"><a href="https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/2-15.jpeg" style="box-sizing: inherit; color: rgb(10, 113, 192); transition: 0.2s; border-color: rgb(10, 113, 192); display: flex; flex-direction: column; flex: 1 0 0%; margin: 0px; height: 182.906px; object-fit: cover; width: 274.656px;"><img loading="lazy" decoding="async" width="925" height="600" data-id="12631" src="https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/2-15-925x600.jpeg" alt="" class="wp-image-12631" srcset="https://toguhaber.gop.edu.tr/wp-content/uploads/sites/7/2026/04/2-15-925x600.jpeg 925w, https://